parameters.jsCode:
// 上游「有永慶連結?」已經保證 ycUrl 是永慶/台慶的買賣件連結，這裡不拿 KEIS 的 official_url
// （houseol 網址）頂替——頂替一定被 KEIS 打槍 400，反而做出沒登錄的孤兒廣告。
// 2026-08-05：official_url 已完全退場（Notion「來源連結」欄同時刪除），這裡只認 ycUrl。
const ctx = $('取貼文結果').first().json;
const road = String(ctx['地址'] || '').replace(/^.{1,3}?[縣市]/, '');
return [{ json: { ...ctx, ycUrl: ctx.ycUrl || '', adcaseRoad: road } }];

// 取 KEIS 新增回來的 adcase_id（失敗不擋流程，只記下原因給 LINE 顯示）
const ctx = $('解析永慶連結').first().json;
const r = $input.first().json || {};
const body = r.body ?? r;
const status = Number(r.statusCode ?? 0);
const adcaseId = body && body.adcase_id ? Number(body.adcase_id) : null;
const msg = (body && body.message) ? String(body.message) : '';
let note;
if (adcaseId) {
  note = String(ctx.ycMatch || '').includes('備援') || String(ctx.ycMatch || '').includes('社區名')
    ? `已同步（連結來源：${ctx.ycMatch}）` : '已同步';
} else if (/已經新增過此官網連結/.test(msg)) {
  // KEIS 擋同一個官網連結重複建檔，回 500 但其實是 400。這代表 KEIS 上早就有這筆了。
  note = 'KEIS 上已有同連結的廣告，未重複建立';
} else {
  note = `建立失敗（HTTP ${status}）${msg ? ' ' + msg.slice(0, 150) : ''}`;
}

// 這班若有被「查無永慶連結」跳過的候補，順便在同一則通知裡講掉，不另外推播洗版
const seen = new Set(); const sk = [];
for (let i = 0; i < 6; i++) {
  let items;
  try { items = $('跳過無連結').all(0, i); } catch (e) { break; }
  if (!items || !items.length) break;
  for (const it of items) {
    const j = it.json || {};
    if (j.contract_no && !seen.has(j.contract_no)) { seen.add(j.contract_no); sk.push(j); }
  }
}
const skipNote = sk.length
  ? `\n\n⏭ 本班先跳過 ${sk.length} 件（查無永慶官網連結，下一班會再試）：\n` + sk.map(x => `・${x.contract_no} ${x.ycNote}`).join('\n')
  : '';

return [{ json: { ...ctx, keisAdcaseId: adcaseId, keisNote: note, skipNote } }];

// API 體檢：KEIS 又砍欄位的話，這裡先擋下來，不要再靜悄悄空轉
const body = $input.first().json;
const items = body.items || body.data || (Array.isArray(body) ? body : []);
// show_in_web 是紅線欄位（標記不上網的案子絕對不能發），被砍掉要當場告警，不能靜靜當成 false
// 2026-08-05：official_url 移出體檢清單——它只餵過 Notion「來源連結」，那欄已刪，沒人再讀它
const need = ['contract_no', 'case_price', 'image_count', 'is_active', 'houseol_created_at', 'show_in_web'];
const sample = items[0] || {};
const missing = need.filter(k => !(k in sample));
return [{ json: { _healthy: items.length > 0 && missing.length === 0, _missing: missing, _count: items.length, _body: body } }];

// 永慶官網補資料 v5（2026-08-01 加撞號防線：編號數字對上還要行政區＋佐證；土地案佐證用地坪/地段名）
// 比對＝**物件編號對物件編號**，一把鑰匙一道鎖：
//   官網每個物件頁的 JSON-LD 裡有 "productID"，例 KEIS 的 PG0092558 → 官網寫 YC0092558、
//   EG0501408 → TC0501408（YC=永慶、TC=台慶、YE=永義，字母前綴各家不同，**數字部分完全一致**）。
//   所以只比數字，字母一律砍掉。
// 為什麼還要「逐筆檢查」而不是直接取搜尋結果第一筆：官網搜尋結果的 JSON-LD 第一筆 url 是壞的，
//   永遠寫成 house/4308114（台北信義區的某物件），第二筆才是真的。搜「0092558」「0501408」
//   「橋都路」「交響樂」第一筆都是它。取第一筆＝每次都接到同一個不相干的物件頁。
// 備援（只在候選頁面全都讀不到 productID 時才啟用，＝官網改版拿掉了這個欄位）：
//   舊的「識別（案名／社區／路名）+ 佐證（總價／權狀坪／建物坪）」評分。留著是為了官網改版時
//   整條線不會直接停擺，但有 productID 就一律以 productID 為準，對不上就是沒有，不猜。
// 補回：屋齡、學區；並交叉驗證格局樓層，不一致就留白
const UA = { 'user-agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/126 Safari/537.36', 'accept-language': 'zh-TW,zh;q=0.9' };
const http = (opt) => this.helpers.httpRequest(opt);
const results = [];

// 2026-07-26 使用者要求：官網查無學區/屋齡時，別讓 Gemini 看到 KEIS 賣點裡提到的相關字句——
// 賣點常見「近學區」這類寫法，屬實但官網沒登記，靠事後的數字守門員整篇擋掉太浪費（AG1927883
// 就是撞到這個：文案照賣點原文寫「近學區」，官網學區欄空白，整篇被判「腦補」打回，Notion 連
// 列都不會建，若無候補接棒下一班還會再抓到同一件、再擋一次）。從源頭砍掉這類子句，Gemini 就
// 沒有材料能寫，比事後擋掉一整篇文案更好；標題也是由賣點素材延伸，砍了子句標題自然也不會提到。
const stripTopic = (text, re) => String(text || '')
  .split(/([，。、\s])/)
  .filter((seg, i) => !(i % 2 === 0 && re.test(seg)))
  .join('')
  .replace(/^[，。、\s]+/, '')
  .replace(/[，、]{2,}/g, '，')
  .replace(/[，、]\s*(?=。|$)/g, '')
  .trim();

