    // 搜編號候選頁是當天剛上架的空殼頁比不中，但社區名「時代爵邸」21 筆候選裡有正確那筆）。
    if (!hit && !backup && via === '編號搜尋' && community) {
      const cands2 = await searchList(city, community);
      for (const u of cands2.slice(0, 8)) {
        if (cands.includes(u)) continue;
        let p;
        try { p = String(await http({ url: u, json: false, timeout: 20000, headers: UA })); } catch (e) { continue; }
        const houseId = (u.match(/\/house\/(\d+)/) || [])[1] || '';
        const t = p.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
