      const isLand = /土地|農|廠|車位/.test(String(src['建物類型'] || ''));
      if (!isLand && ycLayout && src['格局']) {
        // 2026-08-07 修：以前不一致就清空，清空後文案若仍帶格局描述會被數字守門員誤擋（YG0134508 案例）。
        // 官網是公開可驗證來源，不一致時改採官網值，而不是兩邊都不信。
        if (!eq(ycLayout, src['格局'])) { out['格局'] = ycLayout; out['交叉檢查'].push(`格局不一致(KEIS ${src['格局']} / 官網 ${ycLayout})，採用官網值`); }
