  // 查不到的下場＝這件整件跳過、換候補下一件，見下游的「有永慶連結?」門檻

  // 官網沒有學區/屋齡就把賣點裡對應的子句砍掉，別讓 Gemini 有機會照抄進文案（見上方 2026-07-26 註解）
  let sellingPoints = src['賣點'] || [];
  if (!out['學區']) sellingPoints = sellingPoints.map(t => stripTopic(t, /學區|國小|國中/));
  if (out['屋齡'] == null) sellingPoints = sellingPoints.map(t => stripTopic(t, /屋齡|年新|新成屋|中古/));
  out['賣點'] = sellingPoints.filter(Boolean);

  results.push({ json: { ...src, ...out } });
}
return results;

// 數字守門員 v2：
// (1) 文案裡的每個數字都要在官方事實裡找得到
// (2) 官方沒有的欄位（屋齡/學區），文案裡連提都不准提——擋 AI 自己腦補
const j = $input.first().json;

// 2026-08-07 修：KEIS 賣點原文常用全形數字（例如 １１３），AI 產文案時會自動轉半形寫出「113」，
// 但這裡比對事實出處時只認半形，全形數字抓不到 → 明明有出處卻被判「查無出處」。
// 先把用來比對的原文統一轉半形，兩邊比對才會對上。
const toHalf = s => String(s).replace(/[\uFF10-\uFF19]/g, c => String.fromCharCode(c.charCodeAt(0) - 0xFEE0));

const facts = new Set();
const push = v => {
  if (v === null || v === undefined || v === '') return;
  const n = String(v).replace(/,/g, '');
  facts.add(n);
  if (/^\d+\.\d+$/.test(n)) { facts.add(String(Math.round(Number(n)))); facts.add(n.split('.')[0]); }
  if (/^\d+$/.test(n)) facts.add(String(Number(n)));
};
[j['總價萬'], j['單價'], j['主建坪'], j['建物坪'], j['屋齡']].forEach(push);
const raw = toHalf([j['格局'], j['樓層'], j['地址'], j['案名'], j['社區'], j['車位'], j['學區'],
  ...(j['賣點'] || []), ...Object.values(j['機能'] || {})].join(' '));
(raw.match(/\d+(?:\.\d+)?/g) || []).forEach(push);
// 2026-08-07 修：民國日期常寫成「117.04.24」，被上面那行貪婪比對合成「117.04」+「24」兩個 token，
// 月份「04」／「4」從沒進過事實庫——EG0501418 案例：租期「117.04.24」，文案寫「117年4月24日」，
// 「4」就被判查無出處。日期三段分開各自也算數字出處。
(raw.match(/\d{1,4}\.\d{1,2}\.\d{1,2}/g) || []).forEach(d => d.split('.').forEach(push));
['0912877583', '11034791100', '417208', '111'].forEach(push);

const fb = String(j['粉專文案'] || '');
const grp = String(j['社團文案'] || '');
const body = fb + '\n' + grp;

// (1) 數字檢查（先把網址拿掉，LINE 連結的亂碼裡有數字，不是文案在講的數字）
// 2026-08-07 修：「7-11」是超商代稱不是數字宣稱，AA1076686 案例把「11」判成查無出處——
// 賣點原文寫的是「7-ELEVEN」，AI 改寫成慣用的「7-11」，兩者是同一件事，不該被當成編造的數字
const scan = body.replace(/https?:\/\/\S+/g, ' ').replace(/7-11\b/gi, ' 7-ELEVEN ');
const used = [...new Set((scan.match(/\d+(?:\.\d+)?/g) || []))];
const badNums = used.filter(n => !facts.has(n) && !facts.has(String(Number(n))));

// (2) 沒資料就不准提
const banned = [];
if (j['屋齡'] === null || j['屋齡'] === undefined || j['屋齡'] === '') {
  if (/屋齡|年新|新成屋|中古/.test(body)) banned.push('屋齡（官方沒這筆資料）');
}
if (!j['學區']) {
  // 2026-08-07 修：捷運站常以鄰近學校命名（例：O14鳳山國中站），regex 抓到「國中」就誤判成學區宣稱；
  // 加負向 lookahead，緊接著是「站」或「捷運站」的不算
  if (/(學區|國小|國中)(?!(?:捷運)?站)/.test(body)) banned.push('學區（官方沒這筆資料）');
}
if (!j['格局'] && /\d+房\d+廳/.test(body)) banned.push('格局（官方沒這筆資料）');
if (!j['樓層'] && /\d+\s*\/\s*\d+\s*樓|樓層/.test(body)) banned.push('樓層（官方沒這筆資料）');

const ctx = n => {
  const i = body.indexOf(n);
  return i < 0 ? '' : body.slice(Math.max(0, i - 12), i + 12).replace(/\n/g, ' ');
};
// (3) 出貨前形狀檢查（2026-08-03 加）：
// AI 回傳格式壞掉時，整包 JSON 會被當文案發出去。這裡是最後一道，寧可不發也不要貼垃圾。
const len = j['_主體長度'] || {};
const 殘骸 = [];
if (/"粉專主體"|"社團主體"|\\n|```/.test(body)) 殘骸.push('文案裡有 JSON／程式殘骸，AI 回傳格式壞掉');
if (typeof len.fb === 'number' && len.fb < 60) 殘骸.push(`粉專主體只有 ${len.fb} 字，不像正常文案`);
if (typeof len.grp === 'number' && len.grp < 15) 殘骸.push(`社團主體只有 ${len.grp} 字，不像正常文案`);

// (4) 交叉審核（2026-08-04 加）：第二個模型當路人看過一遍，抓語意層的問題
// （混到別間物件、前後矛盾、不像人寫的）。SKIP＝審核員自己壞掉，一律放行。
const 審核 = [];
if (j['_reviewVerdict'] === 'NG') 審核.push(String(j['_reviewReason'] || '審核員未說明原因'));

const ok = badNums.length === 0 && banned.length === 0 && 殘骸.length === 0 && 審核.length === 0;
const msg = ok ? '' :
  `⚠️ ${j.contract_no} 這篇沒發，文案沒過檢查：\n` +
  (badNums.length ? `・查無出處的數字：${badNums.map(n => `${n}（…${ctx(n)}…）`).join('；')}\n` : '') +
  (banned.length ? `・不該提的項目：${banned.join('、')}\n` : '') +
  (殘骸.length ? `・文案本身壞掉：${殘骸.join('、')}\n` : '') +
  (審核.length ? `・交叉審核擋下：${審核.join('、')}\n` : '') +
  `Notion 已建草稿列（狀態=草稿），下一班不會再抓到同一件；要發請手動處理。`;

return [{ json: { ...j, _guardOk: ok, _guardBad: badNums, _guardBanned: banned, _guardJunk: 殘骸, _guardReview: 審核, _guardMsg: msg } }];

// 解壓後所有照片在同一筆的多個 binary 欄位裡，拆成一筆一張，最多 10 張（FB 單篇上限）
const item = $input.first();
const bin = item.binary || {};
const keys = Object.keys(bin).sort((a, b) => String(bin[a].fileName || a).localeCompare(String(bin[b].fileName || b), 'en', { numeric: true }));
const pick = keys.filter(k => /image\//.test(bin[k].mimeType || '')).slice(0, 10);
if (!pick.length) return [];
return pick.map((k, i) => ({ json: { idx: i, fileName: bin[k].fileName }, binary: { photo: bin[k] } }));

const src = $('收集 media id').first().json;
const mode = (() => { try { return $('判斷補救方式').first().json.mode; } catch (e) { return ''; } })();
const why = mode === 'retry'
  ? '已確認沒發出去並自動重發一次，仍然失敗。'
  : '無法向 FB 確認到底發出去了沒，為了避免重複貼文，這次不重發。';
const text = [
  '❌ 廣告沒發出去（Facebook 那邊出錯）',
  '',
  `🏷 ${src.contract_no}　💰 ${src['總價萬']} 萬`,
  `📋 ${src['案名'] || ''}`,
  `📍 ${src['地址'] || ''}`,
  '',
  why,
  'ℹ️ 已把 Notion 待發列撤掉，下一班會自動重抓這件，不用手動處理。',
].join('\n');
return [{ json: { userId: 'Ufab42c56b2eb9b9a9ff18c367b85a6dd', text } }];

// 只讀不寫，判斷 FB 那篇到底發出去了沒
const r = $input.first().json || {};
const fbids = ($('收集 media id').first().json.fbids) || [];
let mode;
if (r.page_story_id) mode = 'ok';        // 照片已被組成一篇貼文 → 極可能其實成功了
else if (r.error) mode = 'giveup';       // 問不到 FB，不敢賭，寧可等下一班
else if (!fbids.length) mode = 'giveup'; // 純文字貼文沒得驗，同樣不賭
else mode = 'retry';                     // 確認沒發出去 → 重發不會重複
return [{ json: { mode, page_story_id: r.page_story_id || '' } }];

// 造一個跟「FB 發貼文」成功時一樣的回應，讓後面的流程照常跑完
// （Notion 標已發布 → 解析永慶連結 → KEIS 新增廣告 → LINE 發布通知）
return [{ json: { id: $('判斷補救方式').first().json.page_story_id, _recovered: true } }];

// 沒有永慶官網連結就整件不發：FB 發了但 KEIS 廣告追蹤建不起來，會變成沒登錄的孤兒廣告，
// 是會被開罰的風險。這裡只記下來、直接回「逐件嘗試」換候補下一件，全自動不卡人。
// 不建 Notion 列 → 下一班還會再抓到同一件；新案的官網頁面常常晚幾小時才上，讓它自己重試。
const j = $input.first().json;
return [{ json: {
  contract_no: j.contract_no,
  案名: j['案名'] || '',
  ycNote: j.ycNote || '',
  skippedAt: new Date().toISOString(),
} }];

// 候補全部跑完都沒發成功時的收尾：如果是因為「查無永慶連結」被跳過，講一聲；
// 單純沒有新案可發（跳過清單是空的）就安靜結束，不要每 2 小時洗一則 LINE。
const seen = new Set();
const sk = [];
for (let i = 0; i < 6; i++) {
  let items;
  try { items = $('跳過無連結').all(0, i); } catch (e) { break; }
  if (!items || !items.length) break;
  for (const it of items) {
    const j = it.json || {};
    if (j.contract_no && !seen.has(j.contract_no)) { seen.add(j.contract_no); sk.push(j); }
  }
}
if (!sk.length) return [];
const text = `⏭ 這班沒發成品：${sk.length} 件都查不到永慶官網連結\n\n`
  + sk.map(x => `・${x.contract_no} ${x['案名'] || ''}\n　${x.ycNote}`).join('\n')
  + `\n\n沒有官網連結就建不了 KEIS 廣告追蹤，寧可不發。下一班會再試一次。`;
return [{ json: { text } }];

